//! The Echap stalkerware list on the Rust side (29 Sep 2026, his "improve all these faults"): the
//! page already matched INSTALLED apps against it (src/stalkerware.js), but an app FILE waiting in
//! Download or WhatsApp was never compared, and the list's 3,228 sample fingerprints were unused.
//! Data: data/stalkerware.tsv, generated by tools/stalkerware.py, stored deflated by build.rs
//! (package names are strings some pattern rules look for - the 29 Sep self-match lesson).

use std::collections::HashMap;
use std::io::Read;
use std::sync::LazyLock;

include!(concat!(env!("OUT_DIR"), "/stalker.rs"));

pub struct List {
    /// package -> app name
    pub packages: HashMap<String, String>,
    /// certificate SHA-1, UPPERCASE hex -> app name
    pub certs: HashMap<String, String>,
    /// APK SHA-256 -> app name
    pub samples: HashMap<[u8; 32], String>,
}

pub static LIST: LazyLock<List> = LazyLock::new(|| {
    let mut t = String::new();
    flate2::read::DeflateDecoder::new(STALKER_Z).read_to_string(&mut t).expect("stalkerware list");
    let mut l = List { packages: HashMap::new(), certs: HashMap::new(), samples: HashMap::new() };
    for line in t.lines().filter(|x| !x.starts_with('#')) {
        let mut p = line.splitn(3, '\t');
        let (Some(kind), Some(key), Some(name)) = (p.next(), p.next(), p.next()) else { continue };
        match kind {
            "P" => { l.packages.insert(key.to_string(), name.to_string()); }
            "C" => { l.certs.insert(key.to_ascii_uppercase(), name.to_string()); }
            "S" => {
                if let Some(h) = crate::hashlist::parse_hex(key) {
                    l.samples.insert(h, name.to_string());
                }
            }
            _ => {}
        }
    }
    l
});

/// The stalkerware app this package or certificate belongs to, if any.
pub fn app_for(package: Option<&str>, certs: &[String]) -> Option<String> {
    let l = &*LIST;
    package.and_then(|p| l.packages.get(p).cloned())
        .or_else(|| certs.iter().find_map(|c| l.certs.get(&c.to_ascii_uppercase()).cloned()))
        .or_else(|| test_cert(certs))
}

// Tests only: no listed maker's key can sign a fixture, so a test names its own throwaway key's
// SHA-1 here to prove the deep look really passes an app FILE's certificates to app_for.
#[cfg(test)]
thread_local! {
    pub static TEST_CERT: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
}

#[cfg(test)]
fn test_cert(certs: &[String]) -> Option<String> {
    TEST_CERT.with(|t| t.borrow().as_ref().filter(|w| certs.iter().any(|c| c.eq_ignore_ascii_case(w))).map(|_| "Test stalker".to_string()))
}

#[cfg(not(test))]
fn test_cert(_: &[String]) -> Option<String> {
    None
}

/// Is this file (by SHA-256) one of the collected stalkerware samples?
pub fn sample(sha: &[u8; 32]) -> Option<&'static str> {
    LIST.samples.get(sha).map(|s| s.as_str()).or_else(|| test_sample(sha))
}

// Tests only: no real spy app may sit on disk, so a test names a harmless file's SHA-256 here to
// prove a sweep passes a file's fingerprint to `sample`. Process-wide (the sweep reads on its own
// threads); only the exact fingerprint a test adds can ever match.
#[cfg(test)]
pub static TEST_SAMPLES: std::sync::Mutex<Vec<[u8; 32]>> = std::sync::Mutex::new(Vec::new());

#[cfg(test)]
fn test_sample(sha: &[u8; 32]) -> Option<&'static str> {
    TEST_SAMPLES.lock().unwrap_or_else(|p| p.into_inner()).contains(sha).then_some("Test stalker")
}

#[cfg(not(test))]
fn test_sample(_: &[u8; 32]) -> Option<&'static str> {
    None
}
